svg.script:
(function(){
  var C = {"CX": 880, "CY": 468, "TH": 86.0, "RINGS": [[290, -115], [230, 0], [172, 80], [118, 170], [54, 300]], "GOLD": "#00D9FF", "COOL": "#9A9AA4", "SRC": 290, "OUT": 230, "L1": 172, "L2": 118, "IN": 54, "BAND": 237, "angles": [-128.57, -102.8557, -77.1414, -51.4271, -25.7129, 0.0014, 25.7157, 51.43, 77.1443, 102.8586, 128.5729, 154.2871, 180.0014, 205.7157], "spokes": [-120, -60, 0, 60, 120, 180], "codeAngles": [-90, -30, 30, 90, 150, 210]};
  var svg = document.documentElement, TAU = Math.PI/180;
  var $ = function(id){ return document.getElementById(id); };

  function depth(r){
    var R = C.RINGS;
    for (var i=0;i<R.length-1;i++){
      if (r <= R[i][0] && r >= R[i+1][0])
        return R[i][1] + (R[i+1][1]-R[i][1])*(R[i][0]-r)/(R[i][0]-R[i+1][0]);
    }
    return r > R[0][0] ? R[0][1] : R[R.length-1][1];
  }
  function liftOf(th){
    var s = Math.sin(th*TAU), c = Math.cos(th*TAU), top = 1e9, bot = -1e9;
    for (var i=0;i<C.RINGS.length;i++){
      var r = C.RINGS[i][0], h = C.RINGS[i][1];
      top = Math.min(top, C.CY + h*s - r*c);
      bot = Math.max(bot, C.CY + h*s + r*c);
    }
    return (top + bot)/2 - (C.CY - 40*s);
  }
  function P(r, deg, th){
    var t = deg*TAU, s = Math.sin(th*TAU), c = Math.cos(th*TAU);
    return [C.CX + r*Math.cos(t), C.CY + r*Math.sin(t)*c + depth(r)*s - liftOf(th)];
  }
  function cyOf(r, th){ return C.CY + depth(r)*Math.sin(th*TAU) - liftOf(th); }
  function ell(el, r, th){
    el.setAttribute('cx', C.CX); el.setAttribute('cy', cyOf(r, th).toFixed(2));
    el.setAttribute('rx', r);    el.setAttribute('ry', (r*Math.cos(th*TAU)).toFixed(2));
  }
  function ringPath(r, th){                      // a full ellipse as a closed path
    var cy = cyOf(r, th), ry = (r*Math.cos(th*TAU)).toFixed(2);
    return 'M'+(C.CX-r)+','+cy.toFixed(2)+' A'+r+','+ry+' 0 1,0 '+(C.CX+r)+','+cy.toFixed(2)+
           ' A'+r+','+ry+' 0 1,0 '+(C.CX-r)+','+cy.toFixed(2)+' Z';
  }

  var NS = 'http://www.w3.org/2000/svg';
  var srcDots = $('srcDots'), parts = $('particles');
  var dots = C.angles.map(function(){
    var e = document.createElementNS(NS,'circle');
    e.setAttribute('r', 4.2); e.setAttribute('fill', C.COOL);
    srcDots.appendChild(e); return e;
  });
  var NP = C.angles.length * 3, pl = [];
  for (var i=0;i<NP;i++){
    var e = document.createElementNS(NS,'circle');
    e.setAttribute('r', 2.4); parts.appendChild(e);
    pl.push({ang: C.angles[i % C.angles.length], off: (i*0.618034) % 1, el: e});
  }
  var spokeEls = Array.prototype.slice.call(document.querySelectorAll('#spokes .spoke'));
  var codeEls  = Array.prototype.slice.call(document.querySelectorAll('#codes .code'));

  function draw(th, tt, clock){
    var c = Math.cos(th*TAU);
    ell($('srcRing'), C.SRC, th);
    ell($('lane1'), C.L1, th); ell($('lane2'), C.L2, th);
    ell($('erpDisc'), C.IN, th); ell($('dtOutlet'), C.IN, th);
    ell($('dtRim'), C.BAND, th);

    // the body: one filled annulus, outer rim to outlet
    $('dtBodyPlan').setAttribute('d', ringPath(C.OUT, th) + ' ' + ringPath(C.IN, th));
    $('dtBodyPlan').setAttribute('opacity', Math.max(0, 1 - tt*2.2).toFixed(3));

    // the same body seen in section
    var ml = P(C.OUT,180,th), mr = P(C.OUT,0,th), nl = P(C.IN,180,th), nr = P(C.IN,0,th);
    $('coneBody').setAttribute('d',
      'M'+ml[0].toFixed(1)+','+ml[1].toFixed(1)+' L'+nl[0].toFixed(1)+','+nl[1].toFixed(1)+
      ' A'+C.IN+','+(C.IN*c).toFixed(2)+' 0 0,0 '+nr[0].toFixed(1)+','+nr[1].toFixed(1)+
      ' L'+mr[0].toFixed(1)+','+mr[1].toFixed(1)+
      ' A'+C.OUT+','+(C.OUT*c).toFixed(2)+' 0 0,0 '+ml[0].toFixed(1)+','+ml[1].toFixed(1)+' Z');
    $('coneBody').setAttribute('opacity', Math.max(0, Math.min(1,(tt-0.14)/0.4)).toFixed(3));

    // radial module divisions — only meaningful looking down
    for (var i=0;i<spokeEls.length;i++){
      var g = C.spokes[i], d = '';
      [C.OUT, C.L1, C.L2, C.IN].forEach(function(r, k){
        var p = P(r, g, th); d += (k ? ' L' : 'M') + p[0].toFixed(1) + ',' + p[1].toFixed(1);
      });
      spokeEls[i].setAttribute('d', d);
      var mid = P((C.OUT + C.L1)/2, C.codeAngles[i], th);
      codeEls[i].setAttribute('x', mid[0].toFixed(1));
      codeEls[i].setAttribute('y', (mid[1]+6).toFixed(1));
    }
    var po = Math.max(0, 1 - tt*3.2);
    $('spokes').setAttribute('opacity', po.toFixed(3));
    $('codes').setAttribute('opacity', po.toFixed(3));
    $('nameplate').setAttribute('opacity', po.toFixed(3));
    $('erpLabel').setAttribute('opacity', po.toFixed(3));
    $('lane1').setAttribute('stroke-opacity', (0.3 + 0.15*tt).toFixed(3));
    $('lane2').setAttribute('stroke-opacity', (0.3 + 0.15*tt).toFixed(3));

    for (var k=0;k<dots.length;k++){
      var p = P(C.SRC, C.angles[k], th);
      dots[k].setAttribute('cx', p[0].toFixed(1)); dots[k].setAttribute('cy', p[1].toFixed(1));
    }

    // data travels in cool, and turns gold the moment it crosses into DataTwin
    for (var j=0;j<pl.length;j++){
      var u = (clock/4.6 + pl[j].off) % 1;
      var r = C.SRC + (C.IN - C.SRC)*u;
      var q = P(r, pl[j].ang + u*16, th);
      pl[j].el.setAttribute('cx', q[0].toFixed(1));
      pl[j].el.setAttribute('cy', q[1].toFixed(1));
      pl[j].el.setAttribute('fill', r > C.BAND ? C.COOL : C.GOLD);
      var f = Math.min(1, u/0.08) * Math.min(1, (1-u)/0.12);
      pl[j].el.setAttribute('opacity', (0.35 + 0.55*f).toFixed(3));
    }

    // the mark rides the rim: the wrapper's edge in plan, the funnel's top in section
    var ph = (clock * (360/16)) - 90;
    var mp = P(C.BAND, ph, th);
    var front = (Math.sin(ph*TAU) + 1) / 2;
    var sc = 1 - tt*0.16*(1-front);
    var om = $('orbitFront');
    om.setAttribute('transform', 'translate('+mp[0].toFixed(1)+','+mp[1].toFixed(1)+') scale('+sc.toFixed(3)+')');
    om.setAttribute('opacity', (1 - tt*0.32*(1-front)).toFixed(3));

    var eo = Math.max(0, (tt-0.62)/0.38);
    $('planOnly').setAttribute('opacity', po.toFixed(3));
    $('capPlan').setAttribute('opacity', po.toFixed(3));
    $('elevOnly').setAttribute('opacity', eo.toFixed(3));
    $('capElev').setAttribute('opacity', eo.toFixed(3));
  }

  function ease(x){ return x<0.5 ? 4*x*x*x : 1-Math.pow(-2*x+2,3)/2; }
  var HOLD0=2.2, ROT=2.4, HOLD1=4.4, LOOP=HOLD0+ROT+HOLD1+ROT;
  function autoT(s){
    s = s % LOOP;
    if (s < HOLD0) return 0;
    if (s < HOLD0+ROT) return ease((s-HOLD0)/ROT);
    if (s < HOLD0+ROT+HOLD1) return 1;
    return 1 - ease((s-HOLD0-ROT-HOLD1)/ROT);
  }

  var manual=false, target=0, cur=0, lastTouch=0, t0=null, frozen=null, frozenClock=null;
  svg.style.cursor='pointer';
  svg.addEventListener('click', function(){
    manual = true; target = target > 0.5 ? 0 : 1; lastTouch = performance.now()/1000;
  });
  function frame(ts){
    if (t0===null) t0 = ts;
    var s = (ts - t0)/1000;
    if (frozen !== null){ draw(frozen*C.TH, frozen, frozenClock===null ? s : frozenClock);
                          requestAnimationFrame(frame); return; }
    if (manual){
      cur += (target - cur) * 0.10;
      if (s - lastTouch > 18 && Math.abs(target-cur) < 0.01 && target === 0){ manual = false; t0 = ts; }
    } else {
      cur = autoT(s); target = cur > 0.5 ? 1 : 0;
    }
    draw(cur*C.TH, cur, s);
    requestAnimationFrame(frame);
  }
  requestAnimationFrame(frame);

  window.__dtSet = function(t, clock){ frozen = t; frozenClock = (clock===undefined ? null : clock);
                                       draw(t*C.TH, t, clock||0); };
  window.__dtLoop = LOOP;
  window.__dtAuto = autoT;
})();
